const runStartedAt = new Date().toISOString();

return [
  {
    json: {
      run_started_at: runStartedAt,
    },
  },
];

const root = $input.first()?.json ?? {};
const entries = Array.isArray(root.entries) ? root.entries : [];
const statusCode = Number(root.statusCode ?? root.status ?? root.error?.statusCode ?? root.error?.status ?? 0);
const hasHttpError = Boolean(root.error) || (Number.isFinite(statusCode) && statusCode >= 400);
const tier1Succeeded = !hasHttpError && Array.isArray(root.entries);

return [
  {
    json: {
      tier1_succeeded: tier1Succeeded,
      entries: tier1Succeeded ? entries : [],
      sourceTotalCount: Number.isFinite(Number(root.totalCount)) ? Number(root.totalCount) : null,
      tier1_status_code: Number.isFinite(statusCode) && statusCode > 0 ? statusCode : null,
      fallbackSummary: {
        mode: tier1Succeeded ? 'list_full' : 'per_id_only',
        failed_list_pages: [],
        list_discovered_count: tier1Succeeded ? entries.length : 0,
        known_gap_count: 0,
        per_id_fetched_count: 0,
        per_id_failures: [],
      },
    },
  },
];

const tier1 = $('Normalize Active Agreement List Result').first().json;
const seen = new Set();
const rows = [];

for (const agreement of tier1.entries ?? []) {
  const relationshipId = agreement.relationship?.id ?? agreement.relationship_id ?? agreement.id;
  if (!relationshipId || seen.has(relationshipId)) continue;
  seen.add(relationshipId);
  rows.push({
    json: {
      relationshipId,
      agreementName: agreement.name ?? agreement.agreementName ?? null,
      clientBusinessName: agreement.client?.business?.name ?? null,
      listAgreement: agreement,
      isKnownGap: false,
      sourceTotalCount: tier1.sourceTotalCount,
      run_started_at: $('Start Invoice Sync Run').first().json.run_started_at,
      fallbackSummary: tier1.fallbackSummary,
      knownGapIds: [],
    },
  });
}

return rows;

const tier1 = $('Normalize Active Agreement List Result').first().json;
if (tier1.tier1_succeeded) return [];

const safeCeiling = 250;
const knownTotalCount = Number(tier1.sourceTotalCount);
const maxPages = Number.isFinite(knownTotalCount) && knownTotalCount > 0
  ? Math.min(knownTotalCount, safeCeiling)
  : safeCeiling;

return Array.from({ length: maxPages }, (_, index) => ({
  json: {
    page: index + 1,
    limit: 1,
    run_started_at: $('Start Invoice Sync Run').first().json.run_started_at,
  },
}));

const pageItems = $input.all();

return [
  {
    json: {
      paginated_page_count: pageItems.length,
      run_started_at: $('Start Invoice Sync Run').first().json.run_started_at,
    },
  },
];

const tier1 = $('Normalize Active Agreement List Result').first().json;
if (tier1.tier1_succeeded) return [];

function nodeItems(name) {
  try {
    return $(name).all();
  } catch (error) {
    return [];
  }
}

function relationshipIdFromAnchorRecord(record) {
  if (!record || typeof record !== 'object') return null;
  return record.relationship?.id ?? record.relationship_id ?? record.id ?? null;
}

const knownIds = $input.all()
  .map((item) => item.json.anchor_relationship_id)
  .filter(Boolean);
const uniqueKnownIds = [...new Set(knownIds)];

const failedListPages = [];
const discoveredById = new Map();
const paginatedItems = nodeItems('Fetch Paginated Active Agreement Page');

paginatedItems.forEach((item, index) => {
  const pageNumber = Number(item.json.page ?? index + 1);
  const statusCode = Number(item.json.statusCode ?? item.json.status ?? item.json.error?.statusCode ?? item.json.error?.status ?? 0);
  const entries = Array.isArray(item.json.entries) ? item.json.entries : [];
  const failed = Boolean(item.json.error) || (Number.isFinite(statusCode) && statusCode >= 400) || !Array.isArray(item.json.entries);
  if (failed) {
    failedListPages.push(pageNumber);
    return;
  }

  for (const agreement of entries) {
    const relationshipId = relationshipIdFromAnchorRecord(agreement);
    if (!relationshipId || discoveredById.has(relationshipId)) continue;
    discoveredById.set(relationshipId, agreement);
  }
});

const gapIds = uniqueKnownIds.filter((anchor_relationship_id) => !discoveredById.has(anchor_relationship_id));
const fallbackSummary = {
  mode: discoveredById.size > 0 ? 'paginated_with_gaps' : 'per_id_only',
  failed_list_pages: failedListPages,
  list_discovered_count: discoveredById.size,
  known_gap_count: gapIds.length,
  per_id_fetched_count: 0,
  per_id_failures: [],
};

const requestsById = new Map();
for (const [relationshipId, agreement] of discoveredById.entries()) {
  requestsById.set(relationshipId, {
    relationshipId,
    agreementName: agreement.name ?? agreement.agreementName ?? null,
    clientBusinessName: agreement.client?.business?.name ?? null,
    listAgreement: agreement,
    isKnownGap: false,
  });
}
for (const relationshipId of gapIds) {
  requestsById.set(relationshipId, {
    relationshipId,
    agreementName: null,
    clientBusinessName: null,
    listAgreement: null,
    isKnownGap: true,
  });
}

return [...requestsById.values()].map((request) => ({
  json: {
    ...request,
    sourceTotalCount: tier1.sourceTotalCount,
    run_started_at: $('Start Invoice Sync Run').first().json.run_started_at,
    fallbackSummary,
    knownGapIds: gapIds,
  },
}));

const invoiceItems = [];
const overLimitRelationships = [];

function nodeItems(name) {
  try {
    return $(name).all();
  } catch (error) {
    return [];
  }
}

const tier1Requests = nodeItems('Prepare Tier 1 Active Agreement Requests');
const fallbackRequests = nodeItems('Identify Known Active Agreement Gaps');
const sourceRequests = fallbackRequests.length > 0 ? fallbackRequests : tier1Requests;
const firstRequest = sourceRequests[0]?.json ?? {};
const knownGapIds = Array.isArray(firstRequest.knownGapIds) ? firstRequest.knownGapIds : [];
const perIdFailures = [];

for (const [index, item] of $input.all().entries()) {
  const root = item.json;
  const request = sourceRequests[index]?.json ?? {};
  const relationshipId = request.relationshipId ?? root.relationshipId ?? null;
  const statusCode = Number(root.statusCode ?? root.status ?? root.error?.statusCode ?? root.error?.status ?? 0);
  const hasHttpError = Boolean(root.error) || (Number.isFinite(statusCode) && statusCode >= 400);
  const invoices = Array.isArray(root.entries) ? root.entries : [];

  if (hasHttpError || !Array.isArray(root.entries)) {
    if (request.isKnownGap && relationshipId) perIdFailures.push(relationshipId);
    continue;
  }

  if (request.isKnownGap && relationshipId) {
    // The per-ID fallback succeeded even when the agreement currently has no invoices.
  }

  if ((root.totalCount ?? 0) > (root.limit ?? 100)) {
    overLimitRelationships.push({
      relationshipId,
      totalCount: root.totalCount,
      limit: root.limit,
    });
  }

  for (const invoice of invoices) {
    invoiceItems.push({
      json: {
        invoiceId: invoice.id,
        relationshipId,
        listInvoice: invoice,
        overLimitRelationships,
      },
    });
  }
}

const fallbackSummary = {
  ...(firstRequest.fallbackSummary ?? {
    mode: 'list_full',
    failed_list_pages: [],
    list_discovered_count: sourceRequests.length,
    known_gap_count: knownGapIds.length,
    per_id_fetched_count: 0,
    per_id_failures: [],
  }),
  per_id_fetched_count: Math.max(0, knownGapIds.length - perIdFailures.length),
  per_id_failures: perIdFailures,
};

return invoiceItems.map((item) => ({
  json: {
    ...item.json,
    fallbackSummary,
    knownGapIds,
  },
}));

const lastSeenAt = new Date().toISOString();
const explodedInvoice = (() => {
  try {
    return $('Explode Invoices').first().json;
  } catch (error) {
    return {};
  }
})();
const fallbackSummary = explodedInvoice.fallbackSummary ?? {
  mode: 'list_full',
  failed_list_pages: [],
  list_discovered_count: 0,
  known_gap_count: 0,
  per_id_fetched_count: 0,
  per_id_failures: [],
};

function parseMoney(value) {
  if (value === undefined || value === null || value === '') return null;
  if (typeof value === 'number') return value;
  const cleaned = String(value).replace(/[$,]/g, '').trim();
  if (!cleaned) return null;
  const parsed = Number(cleaned);
  return Number.isFinite(parsed) ? parsed : null;
}

function parseNumber(value) {
  if (value === undefined || value === null || value === '') return null;
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function invoiceNote(invoice) {
  return invoice.note ?? invoice.notes ?? invoice.memo ?? invoice.description ?? invoice.message ?? null;
}

function serviceNameForLineItem(lineItem) {
  return lineItem.name
    ?? lineItem.serviceName
    ?? lineItem.service?.name
    ?? lineItem.origin?.serviceBundle?.name
    ?? lineItem.integrations?.quickbooks?.item?.name
    ?? null;
}

function flattenLineItems(invoice, lineItems, parentLineItemId = null) {
  const rows = [];

  for (const lineItem of lineItems ?? []) {
    const children = [
      ...(Array.isArray(lineItem.groupedLineItems) ? lineItem.groupedLineItems : []),
      ...(Array.isArray(lineItem.subItems) ? lineItem.subItems : []),
    ];

    rows.push({
      anchor_line_item_id: lineItem.id,
      anchor_invoice_id: invoice.id,
      anchor_relationship_id: invoice.agreement?.id ?? null,
      parent_line_item_id: parentLineItemId,
      service_id: lineItem.serviceId ?? lineItem.origin?.serviceBundle?.bundleItemId ?? null,
      service_template_id: lineItem.serviceTemplateId ?? lineItem.origin?.serviceBundle?.serviceTemplateId ?? null,
      service_name: serviceNameForLineItem(lineItem),
      name: lineItem.name ?? null,
      amount: parseMoney(lineItem.amount),
      rate: parseMoney(lineItem.rate),
      quantity: parseNumber(lineItem.quantity),
      unit_name: lineItem.unitName ?? null,
      qbo_product_id: lineItem.integrations?.quickbooks?.item?.id ?? null,
      qbo_product_name: lineItem.integrations?.quickbooks?.item?.name ?? null,
      is_bundle_parent: children.length > 0,
      raw: lineItem,
      last_seen_at: lastSeenAt,
    });

    rows.push(...flattenLineItems(invoice, children, lineItem.id));
  }

  return rows;
}

const invoices = $input.all()
  .map((item) => item.json)
  .filter((invoice) => invoice && invoice.id && !invoice.error);
const invoiceRows = invoices.map((invoice) => ({
  anchor_invoice_id: invoice.id,
  anchor_relationship_id: invoice.agreement?.id ?? null,
  invoice_number: invoice.invoiceNumber ?? null,
  issue_date: invoice.issueDate ?? null,
  due_date: invoice.dueDate ?? null,
  total_amount: parseMoney(invoice.totalAmount),
  amount_paid: parseMoney(invoice.amountPaid),
  amount_due: parseMoney(invoice.amountDue),
  display_status: invoice.status?.displayStatus ?? invoice.status?.type ?? null,
  qbo_status: invoice.integrations?.quickbooks?.status ?? null,
  invoice_note: invoiceNote(invoice),
  raw: invoice,
  last_seen_at: lastSeenAt,
}));

const lineRows = invoices.flatMap((invoice) => flattenLineItems(invoice, invoice.lineItems));

return [
  {
    json: {
      invoiceCount: invoiceRows.length,
      lineItemCount: lineRows.length,
      invoiceRows,
      lineRows,
      fallbackSummary,
      sampleInvoices: invoiceRows.slice(0, 5).map((row) => ({
        anchor_invoice_id: row.anchor_invoice_id,
        invoice_number: row.invoice_number,
        anchor_relationship_id: row.anchor_relationship_id,
        total_amount: row.total_amount,
        display_status: row.display_status,
        invoice_note: row.invoice_note,
      })),
      sampleLineItems: lineRows.slice(0, 5).map((row) => ({
        anchor_line_item_id: row.anchor_line_item_id,
        anchor_invoice_id: row.anchor_invoice_id,
        service_name: row.service_name,
        name: row.name,
        amount: row.amount,
        qbo_product_name: row.qbo_product_name,
      })),
    },
  },
];

const rows = $input.all().map((item) => item.json);
const mapped = $('Map Invoice Rows').first().json;
return [
  {
    json: {
      status: 'ok',
      upsertedInvoiceCount: rows.length,
      fallbackSummary: mapped.fallbackSummary,
      sample: rows.slice(0, 5).map((row) => ({
        anchor_invoice_id: row.anchor_invoice_id,
        invoice_number: row.invoice_number,
        total_amount: row.total_amount,
        display_status: row.display_status,
      })),
    },
  },
];

const rows = $input.all().map((item) => item.json);
const mapped = $('Map Invoice Rows').first().json;
return [
  {
    json: {
      status: 'ok',
      upsertedLineItemCount: rows.length,
      fallbackSummary: mapped.fallbackSummary,
      sample: rows.slice(0, 5).map((row) => ({
        anchor_line_item_id: row.anchor_line_item_id,
        anchor_invoice_id: row.anchor_invoice_id,
        name: row.name,
        amount: row.amount,
        qbo_product_name: row.qbo_product_name,
      })),
    },
  },
];
